iversary","birthday","celebration","corporate","date","hangout","reunion","travel"],"new":false,"sp":[{"k":"type","l":"Type","q":"What kind of tour or activity?","b":false,"v":[{"v":"Tour guide","e":["anniversary","birthday","celebration","corporate","date","hangout","reunion","travel"]},{"v":"Team building","e":["corporate","reunion"]},{"v":"Island hopping / day tour","e":["anniversary","birthday","celebration","date","hangout","reunion","travel"]},{"v":"Pilgrimage (Visita Iglesia)","e":["travel"]}]}]},{"k":"restaurant_reservation","n":"Restaurant (reservation)","t":"restaurant_reservation","e":["anniversary","birthday","celebration","christening","corporate","date","debut","gender_reveal","graduation","hangout","reunion","travel","wedding"],"new":false,"sp":[{"k":"also","l":"Also","q":"What can the restaurant offer a group?","b":false,"v":[{"v":"Private room","e":["anniversary","birthday","celebration","christening","corporate","date","debut","gender_reveal","graduation","hangout","reunion","travel","wedding"]},{"v":"Set menu for groups","e":["anniversary","birthday","celebration","christening","corporate","debut","gender_reveal","graduation","hangout","reunion","travel","wedding"]},{"v":"Buyout","e":["anniversary","birthday","celebration","christening","corporate","date","debut","gender_reveal","graduation","hangout","reunion","wedding"]}]}]},{"k":"referee_official","n":"Referees / officials","t":"referee_official","e":["tournament"],"new":false,"sp":[{"k":"sport","l":"Sport","q":"Which sports do you officiate?","b":false,"v":[{"v":"Basketball","e":["tournament"]},{"v":"Volleyball","e":["tournament"]},{"v":"Football / futsal","e":["tournament"]},{"v":"Badminton","e":["tournament"]},{"v":"Boxing","e":["tournament"]},{"v":"Billiards","e":["tournament"]},{"v":"Chess","e":["tournament"]},{"v":"Esports","e":["tournament"]},{"v":"Running / fun run","e":["tournament"]},{"v":"Pageant","e":["tournament"]}]}]},{"k":"event_medic","n":"Medic / first-aid","t":"event_medic","e":["concert","corporate","debut","gala_night","graduation","grand_opening","open_house","reunion","tournament","wedding"],"new":false,"sp":[{"k":"includes","l":"Includes","q":"What do you bring?","b":false,"v":[{"v":"Ambulance on standby","e":["concert","corporate","debut","gala_night","graduation","grand_opening","open_house","reunion","tournament","wedding"]},{"v":"First-aid station","e":["concert","corporate","debut","gala_night","graduation","grand_opening","open_house","reunion","tournament","wedding"]}]}]},{"k":"security_marshals","n":"Security & marshals","t":"event_staffing","e":["celebration","concert","corporate","debut","gala_night","graduation","grand_opening","open_house","reunion","tournament","wake","wedding"],"new":true,"sp":[{"k":"role","l":"Role","q":"What do you provide?","b":false,"v":[{"v":"Security guards","e":["celebration","concert","corporate","debut","gala_night","graduation","grand_opening","open_house","reunion","tournament","wake","wedding"]},{"v":"Traffic & parking marshals","e":["celebration","concert","corporate","debut","gala_night","graduation","grand_opening","open_house","reunion","tournament","wake","wedding"]},{"v":"Crowd control","e":["celebration","concert","corporate","debut","gala_night","graduation","grand_opening","open_house","reunion","tournament","wedding"]},{"v":"Valet parking","e":["celebration","corporate","debut","gala_night","graduation","grand_opening","open_house","reunion","wedding"]}]}]},{"k":"ticketing_registration","n":"Ticketing & registration","t":"event_staffing","e":["celebration","concert","corporate","gala_night","graduation","grand_opening","open_house","reunion","tournament"],"new":true,"sp":[{"k":"includes","l":"Includes","q":"What do you handle?","b":false,"v":[{"v":"Online ticketing","e":["celebration","concert","corporate","gala_night","graduation","grand_opening","open_house","reunion","tournament"]},{"v":"Gate scanning","e":["celebration","concert","corporate","gala_night","graduation","grand_opening","open_house","reunion","tournament"]},{"v":"Registration desk","e":["celebration","concert","corporate","gala_night","graduation","grand_opening","open_house","reunion","tournament"]}]}]},{"k":"ushers_event_staff","n":"Ushers & event staff","t":"event_staffing","e":["anniversary","celebration","concert","corporate","debut","gala_night","graduation","grand_opening","open_house","reunion","tournament","wedding"],"new":true,"sp":[{"k":"role","l":"Role","q":"Who do you provide?","b":false,"v":[{"v":"Ushers / usherettes","e":["anniversary","celebration","concert","corporate","debut","gala_night","graduation","grand_opening","open_house","reunion","tournament","wedding"]},{"v":"Promo models / brand ambassadors","e":["concert","corporate","gala_night","grand_opening","open_house","wedding"]},{"v":"Waiters & bussers","e":["anniversary","celebration","corporate","debut","gala_night","graduation","grand_opening","open_house","reunion","wedding"]}]}]},{"k":"cleanup_crew","n":"Clean-up crew (post-event)","t":"event_staffing","e":["anniversary","birthday","celebration","christening","concert","corporate","debut","gala_night","gender_reveal","graduation","grand_opening","open_house","reunion","tournament","wake","wedding"],"new":true,"sp":[]},{"k":"event_insurance","n":"Insurance","t":"event_insurance","e":["birthday","celebration","concert","corporate","debut","gala_night","graduation","grand_opening","open_house","reunion","tournament","travel","wedding"],"new":false,"sp":[{"k":"cover","l":"Cover","q":"What does your insurance cover?","b":false,"v":[{"v":"Personal accident","e":["birthday","celebration","concert","corporate","debut","gala_night","graduation","grand_opening","open_house","reunion","tournament","travel","wedding"]},{"v":"Travel","e":["corporate","reunion","tournament","travel","wedding"]}]}]},{"k":"reveal_element","n":"Reveal element","t":"reveal_element","e":["gender_reveal"],"new":false,"sp":[{"k":"kind","l":"Kind","q":"What reveal do you supply?","b":false,"v":[{"v":"Balloon pop","e":["gender_reveal"]},{"v":"Smoke / powder","e":["gender_reveal"]},{"v":"Confetti cannon","e":["gender_reveal"]},{"v":"Piñata","e":["gender_reveal"]},{"v":"Sports ball","e":["gender_reveal"]},{"v":"Box release","e":["gender_reveal"]}]}]},{"k":"body_repatriation","n":"Body repatriation","t":"funeral_home","e":["wake"],"new":false,"sp":[]},{"k":"casket","n":"Casket & urn","t":"funeral_home","e":["wake"],"new":false,"sp":[{"k":"type","l":"Type","q":"What do you sell?","b":false,"v":[{"v":"Urn","e":["wake"]}]}]},{"k":"wake_package","n":"Funeral home & wake","t":"funeral_home","e":["wake"],"new":false,"sp":[{"k":"includes","l":"Includes","q":"What does your funeral home include?","b":false,"v":[{"v":"Embalming","e":["wake"]},{"v":"Chapel / viewing","e":["wake"]},{"v":"Home wake setup","e":["wake"]}]}]},{"k":"hearse_funeral_transport","n":"Hearse","t":"funeral_home","e":["wake"],"new":false,"sp":[]},{"k":"memorial_lot","n":"Resting place (lot, mausoleum, niche)","t":"memorial_park","e":["wake"],"new":false,"sp":[{"k":"type","l":"Type","q":"What kind of resting place?","b":false,"v":[{"v":"Columbarium niche","e":["wake"]},{"v":"Mausoleum","e":["wake"]},{"v":"Lapida / headstone","e":["wake"]}]}]},{"k":"cremation_service","n":"Cremation","t":"memorial_park","e":["wake"],"new":false,"sp":[]},{"k":"interment_service","n":"Interment / burial service","t":"memorial_park","e":["wake"],"new":false,"sp":[]},{"k":"prayer_leader","n":"Prayer leader (padasal / novena)","t":"prayers","e":["anniversary","wake"],"new":true,"sp":[{"k":"kind","l":"Kind","q":"What prayers do you lead?","b":false,"v":[{"v":"Rosary at the wake","e":["wake"]},{"v":"Novena (nine nights)","e":["wake"]},{"v":"40th day / death anniversary","e":["anniversary","wake"]}]}]},{"k":"officiant_priest_minister","n":"Officiant","t":"officiants","e":null,"new":false,"hidden":true,"sp":[{"k":"faith","l":"Faith","q":null,"b":false,"v":[{"v":"Aglipayan","e":null},{"v":"Born Again","e":null},{"v":"Buddhist","e":null},{"v":"Catholic","e":null},{"v":"Christian","e":null},{"v":"Civil","e":null},{"v":"Cultural","e":null},{"v":"Hindu","e":null},{"v":"INC","e":null},{"v":"Jewish","e":null},{"v":"JW","e":null},{"v":"LDS","e":null},{"v":"Muslim","e":null},{"v":"Orthodox","e":null},{"v":"SDA","e":null},{"v":"Sikh","e":null}]}]},{"k":"pre_cana_seminar","n":"Pre-marriage seminar / counseling","t":"officiants","e":null,"new":false,"hidden":true,"sp":[{"k":"seminar_type","l":"Seminar","q":null,"b":false,"v":[{"v":"CFO (marrying a foreigner)","e":null}]},{"k":"faith","l":"Faith","q":null,"b":false,"v":[{"v":"Christian","e":null},{"v":"INC","e":null},{"v":"Muslim","e":null},{"v":"Catholic","e":null}]}]}]$map$::jsonb;
  v_counts    JSONB := $map${"categories":39,"services":84,"new_services":16,"specialties":90,"values":371,"live_keys":296,"tile_merges":40,"trade_merges":216}$map$::jsonb;
  r JSONB; t JSONB; sp JSONB; v_res JSONB;
  v_moved JSONB := '{}'::jsonb;
  v_k TEXT; v_v JSONB; v_n INT;
  v_tiles_added INT := 0; v_services_added INT := 0; v_retiled INT := 0;
  v_tiles_merged INT := 0; v_tiles_skipped INT := 0;
  v_trades_merged INT := 0; v_trades_skipped INT := 0;
  v_tagged INT := 0; v_facets_written INT := 0;
  v_facets_refused TEXT[] := ARRAY[]::text[];
  v_schemas_added INT := 0; v_renamed_tiles INT := 0; v_renamed_trades INT := 0;
  v_tile_scopes INT := 0; v_trade_scopes INT := 0;
  v_vendor UUID; v_def JSONB; v_old JSONB; v_min JSONB; v_payload JSONB;
  v_keys TEXT[];
BEGIN
  -- ── 1 · prerequisites ────────────────────────────────────────────────────
  IF to_regprocedure('public.merge_service_category(text,text,uuid)') IS NULL THEN
    RAISE EXCEPTION 'taxonomy v2: merge_service_category() is missing';
  END IF;
  IF to_regprocedure('public.merge_canonical_service(text,text,uuid)') IS NULL THEN
    RAISE EXCEPTION 'taxonomy v2: merge_canonical_service() is missing';
  END IF;

  -- ── 2 · the two new categories ───────────────────────────────────────────
  -- coarse_category: the stored vendor_category a shop under the branch is
  -- filed as (③0-c one source). Every live branch needs one, or its services
  -- land in `misc` (tests/db/no-service-lands-in-misc). Staff, security &
  -- registration → `security` (the enum's own word for it); Prayers & novena →
  -- `officiant`, the category the other rite-leading branch (Officiants) is
  -- filed under. Both are admin-editable in /admin/categories.
  FOR t IN SELECT * FROM jsonb_array_elements(v_new_tiles) LOOP
    INSERT INTO service_categories
      (id, parent_id, tier, kind, label_en, slug, sort_order, scope, status, marketplace_hidden,
       coarse_category)
    SELECT t->>'id', sib.parent_id, 2, 'leaf', t->>'label', replace(t->>'id', '_', '-'),
           COALESCE((SELECT max(sort_order) + 1 FROM service_categories
                      WHERE parent_id = sib.parent_id AND tier = 2), 0),
           'global', 'active', FALSE, (t->>'coarse')::public.vendor_category
      FROM service_categories sib
     WHERE sib.id = t->>'sibling' AND sib.tier = 2
    ON CONFLICT (id) DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_tiles_added := v_tiles_added + v_n;
  END LOOP;

  -- ── 3 · the new services ─────────────────────────────────────────────────
  -- phase: the admin launch badge; a v2 service is released with v2, so it
  -- carries the latest declared phase (lib/taxonomy.ts TaxonomyPhase).
  FOR r IN SELECT * FROM jsonb_array_elements(v_services) WHERE (value->>'new')::boolean LOOP
    INSERT INTO canonical_service_taxonomy
      (canonical_service, folder_id, tile_id, phase, applicable_event_types)
    SELECT r->>'k', sc.parent_id, sc.id, 'V1.5+',
           ARRAY(SELECT jsonb_array_elements_text(r->'e'))
      FROM service_categories sc WHERE sc.id = r->>'t' AND sc.tier = 2
    ON CONFLICT (canonical_service) DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_services_added := v_services_added + v_n;
  END LOOP;

  -- ── 4 · re-tile every key and every service onto its v2 category ─────────
  FOR r IN
    SELECT jsonb_build_object('k', e->>'f', 't', e->>'ic') FROM jsonb_array_elements(v_rows) e
     WHERE NOT (e->>'s')::boolean
    UNION
    SELECT jsonb_build_object('k', e->>'i', 't', e->>'ic') FROM jsonb_array_elements(v_rows) e
     WHERE NOT (e->>'s')::boolean
    UNION
    SELECT jsonb_build_object('k', s->>'k', 't', s->>'t') FROM jsonb_array_elements(v_services) s
  LOOP
    UPDATE canonical_service_taxonomy c
       SET tile_id = r->>'t', folder_id = sc.parent_id, updated_at = NOW()
      FROM service_categories sc
     WHERE sc.id = r->>'t' AND sc.tier = 2 AND sc.merged_into_category_id IS NULL
       AND c.canonical_service = r->>'k'
       AND (c.tile_id IS DISTINCT FROM r->>'t' OR c.folder_id IS DISTINCT FROM sc.parent_id);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_retiled := v_retiled + v_n;
  END LOOP;

  -- ── 5 · fold each category into its destination ──────────────────────────
  FOR t IN SELECT * FROM jsonb_array_elements(v_tiles) LOOP
    IF NOT EXISTS (SELECT 1 FROM service_categories
                    WHERE id = t->>'s' AND tier = 2 AND merged_into_category_id IS NULL)
       OR NOT EXISTS (SELECT 1 FROM service_categories
                    WHERE id = t->>'d' AND tier = 2 AND merged_into_category_id IS NULL) THEN
      v_tiles_skipped := v_tiles_skipped + 1;
      CONTINUE;
    END IF;
    v_res := public.merge_service_category(t->>'s', t->>'d', NULL);
    v_tiles_merged := v_tiles_merged + 1;
    FOR v_k, v_v IN SELECT * FROM jsonb_each(v_res->'moved') LOOP
      v_moved := jsonb_set(v_moved, ARRAY['tile:' || v_k],
        to_jsonb(COALESCE((v_moved->>('tile:' || v_k))::int, 0) + (v_v #>> '{}')::int));
    END LOOP;
  END LOOP;

  -- ── 6 · retire the hidden "Everything else" ──────────────────────────────
  -- STATUS ONLY, NO FORWARD. It holds no trade and is already hidden; it is
  -- still the code fallback home for a couple's SELF-ADDED supplier (`misc`),
  -- and the taxonomy snapshot ignores `status`, so such a supplier keeps
  -- rendering. There is no right destination for "a supplier we could not
  -- name", so none is invented.
  UPDATE service_categories
     SET status = 'retired', marketplace_hidden = TRUE
   WHERE id = 'everything_else' AND tier = 2 AND status IS DISTINCT FROM 'retired';

  -- ── 7 · the 39 categories: v2 label, event scope covering their services ──
  FOR t IN SELECT * FROM jsonb_array_elements(v_labels) LOOP
    UPDATE service_categories SET label_en = t->>'l'
     WHERE id = t->>'t' AND tier = 2 AND merged_into_category_id IS NULL
       AND label_en IS DISTINCT FROM t->>'l';
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_renamed_tiles := v_renamed_tiles + v_n;

    UPDATE service_categories sc
       SET applicable_event_types = u.types
      FROM (
        SELECT ARRAY(
                 SELECT DISTINCT x FROM (
                   SELECT unnest(COALESCE((SELECT applicable_event_types FROM service_categories WHERE id = t->>'t'), ARRAY[]::text[])) AS x
                   UNION
                   SELECT jsonb_array_elements_text(s->'e')
                     FROM jsonb_array_elements(v_services) s
                    WHERE s->>'t' = t->>'t' AND jsonb_typeof(s->'e') = 'array'
                 ) q ORDER BY x) AS types
      ) u
     WHERE sc.id = t->>'t' AND sc.tier = 2
       AND NOT (COALESCE(sc.applicable_event_types, ARRAY[]::text[]) @> u.types);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_tile_scopes := v_tile_scopes + v_n;
  END LOOP;

  -- ── 8 · every service: schema row, v2 name, v2 event scope ───────────────
  FOR r IN SELECT * FROM jsonb_array_elements(v_services) LOOP
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM canonical_service_taxonomy WHERE canonical_service = r->>'k');
    INSERT INTO canonical_service_schemas (canonical_service, display_name_en)
    VALUES (r->>'k', r->>'n')
    ON CONFLICT (canonical_service) DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_schemas_added := v_schemas_added + v_n;
    UPDATE canonical_service_schemas
       SET display_name_en = r->>'n', updated_at = NOW()
     WHERE canonical_service = r->>'k' AND display_name_en IS DISTINCT FROM r->>'n';
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_renamed_trades := v_renamed_trades + v_n;
    IF jsonb_typeof(r->'e') = 'array' THEN
      UPDATE canonical_service_taxonomy
         SET applicable_event_types = ARRAY(SELECT jsonb_array_elements_text(r->'e')), updated_at = NOW()
       WHERE canonical_service = r->>'k'
         AND applicable_event_types IS DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(r->'e'));
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_trade_scopes := v_trade_scopes + v_n;
    END IF;
  END LOOP;

  -- ── 9 · every specialty as a facet ───────────────────────────────────────
  -- Shape (iteration 0044): category_specific_attributes {key: {type, label,
  -- options[]}} + filter_facets [keys]. Pick-all-that-apply = multi_select;
  -- Rental = boolean. `question` and `option_event_types` {value: [event
  -- types]} ride inside the same definition — nothing reads them yet (the
  -- couple facet UI reads type/label/options), so they cost no schema change.
  -- The v2 keys are PREPENDED in v2 order: lib/vendor-facets.ts keeps the
  -- first 6 selectable dimensions.
  FOR r IN SELECT * FROM jsonb_array_elements(v_services) LOOP
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM canonical_service_schemas WHERE canonical_service = r->>'k');
    v_keys := ARRAY[]::text[];
    FOR sp IN SELECT * FROM jsonb_array_elements(r->'sp') LOOP
      SELECT category_specific_attributes->(sp->>'k') INTO v_old
        FROM canonical_service_schemas WHERE canonical_service = r->>'k';
      IF v_old IS NOT NULL AND v_old->>'type' IS DISTINCT FROM
           (CASE WHEN (sp->>'b')::boolean THEN 'boolean' ELSE 'multi_select' END)
         AND NOT (NOT (sp->>'b')::boolean AND v_old->>'type' = 'enum')
         AND v_old->>'v2' IS NULL THEN
        v_facets_refused := v_facets_refused || ((r->>'k') || '.' || (sp->>'k') || ' (is ' || COALESCE(v_old->>'type', '?') || ')');
        CONTINUE;
      END IF;
      v_def := jsonb_build_object(
        'type', CASE WHEN (sp->>'b')::boolean THEN 'boolean' ELSE 'multi_select' END,
        'label', sp->>'l',
        'v2', TRUE);
      IF sp->>'q' IS NOT NULL THEN
        v_def := v_def || jsonb_build_object('question', sp->>'q');
      END IF;
      IF NOT (sp->>'b')::boolean THEN
        v_def := v_def || jsonb_build_object(
          'options', (SELECT jsonb_agg(x->'v' ORDER BY o) FROM jsonb_array_elements(sp->'v') WITH ORDINALITY AS a(x, o)));
      END IF;
      IF EXISTS (SELECT 1 FROM jsonb_array_elements(sp->'v') x WHERE jsonb_typeof(x->'e') = 'array') THEN
        v_def := v_def || jsonb_build_object('option_event_types',
          (SELECT jsonb_object_agg(x->>'v', x->'e') FROM jsonb_array_elements(sp->'v') x
            WHERE jsonb_typeof(x->'e') = 'array'));
      END IF;
      v_keys := v_keys || (sp->>'k');

      UPDATE canonical_service_schemas s
         SET category_specific_attributes = s.category_specific_attributes || jsonb_build_object(sp->>'k', v_def),
             updated_at = NOW()
       WHERE s.canonical_service = r->>'k'
         AND s.category_specific_attributes->(sp->>'k') IS DISTINCT FROM v_def;
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_facets_written := v_facets_written + v_n;
    END LOOP;

    -- filter_facets: the v2 keys first (v2 order), then the rest as they were.
    UPDATE canonical_service_schemas s
       SET filter_facets = to_jsonb(v_keys) || COALESCE((
             SELECT jsonb_agg(x ORDER BY o) FROM jsonb_array_elements(s.filter_facets) WITH ORDINALITY AS a(x, o)
              WHERE NOT (x #>> '{}') = ANY (v_keys)), '[]'::jsonb),
           updated_at = NOW()
     WHERE s.canonical_service = r->>'k'
       AND s.filter_facets IS DISTINCT FROM to_jsonb(v_keys) || COALESCE((
             SELECT jsonb_agg(x ORDER BY o) FROM jsonb_array_elements(s.filter_facets) WITH ORDINALITY AS a(x, o)
              WHERE NOT (x #>> '{}') = ANY (v_keys)), '[]'::jsonb);
  END LOOP;

  -- ── 10 · tag the shops, then fold the trades ─────────────────────────────
  -- Rows arrive SELF-ROWS FIRST (generator order), so a survivor's own tag
  -- (pre_cana_seminar → Catholic) lands before any other key's shops join it.
  FOR r IN SELECT * FROM jsonb_array_elements(v_rows) LOOP
    CONTINUE WHEN (r->>'s')::boolean;
    IF r->>'f' = r->>'i' AND (r->>'fn' IS NULL OR EXISTS (
         SELECT 1 FROM canonical_service_taxonomy WHERE merged_into = r->>'i')) THEN
      CONTINUE;
    END IF;
    IF r->>'f' <> r->>'i' AND EXISTS (
         SELECT 1 FROM canonical_service_taxonomy
          WHERE canonical_service = r->>'f' AND merged_into IS NOT NULL) THEN
      v_trades_skipped := v_trades_skipped + 1;
      CONTINUE;
    END IF;
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM canonical_service_taxonomy WHERE canonical_service = r->>'f')
              OR NOT EXISTS (SELECT 1 FROM canonical_service_taxonomy
                              WHERE canonical_service = r->>'i' AND merged_into IS NULL);

    SELECT required_for_visibility->'minimum_fields' INTO v_min
      FROM canonical_service_schemas WHERE canonical_service = r->>'i';

    FOR v_vendor IN
      SELECT vendor_profile_id FROM vendor_coverages WHERE canonical_service = r->>'f'
      UNION SELECT vendor_profile_id FROM vendor_profiles WHERE services @> ARRAY[r->>'f']
      UNION SELECT vendor_profile_id FROM vendor_services WHERE category = r->>'f'
      UNION SELECT vendor_profile_id FROM vendor_service_attributes WHERE canonical_service = r->>'f'
    LOOP
      CONTINUE WHEN NOT EXISTS (SELECT 1 FROM canonical_service_schemas WHERE canonical_service = r->>'i');

      -- (a) the survivor attribute row, the folded key's own row folded in
      --     (survivor wins a scalar clash; lists union).
      SELECT COALESCE(d.attribute_payload, '{}'::jsonb), COALESCE(src.attribute_payload, '{}'::jsonb)
        INTO v_payload, v_v
        FROM (SELECT 1) one
        LEFT JOIN vendor_service_attributes d
               ON d.vendor_profile_id = v_vendor AND d.canonical_service = r->>'i'
        LEFT JOIN vendor_service_attributes src
               ON src.vendor_profile_id = v_vendor AND src.canonical_service = r->>'f'
                  AND r->>'f' <> r->>'i';
      FOR v_k IN SELECT jsonb_object_keys(v_v) LOOP
        IF NOT v_payload ? v_k THEN
          v_payload := v_payload || jsonb_build_object(v_k, v_v->v_k);
        ELSIF jsonb_typeof(v_payload->v_k) = 'array' AND jsonb_typeof(v_v->v_k) = 'array' THEN
          v_payload := v_payload || jsonb_build_object(v_k,
            (SELECT COALESCE(jsonb_agg(DISTINCT x), '[]'::jsonb)
               FROM (SELECT jsonb_array_elements(v_payload->v_k) x
                     UNION SELECT jsonb_array_elements(v_v->v_k)) u));
        END IF;
      END LOOP;

      -- (b) the specialty value this shop earned by holding the folded key.
      IF r->>'fn' IS NOT NULL AND NOT ((r->>'i') || '.' || (r->>'fn')) = ANY (
           SELECT split_part(x, ' ', 1) FROM unnest(v_facets_refused) x) THEN
        IF r->>'fn' = 'is_rental' THEN
          v_payload := v_payload || jsonb_build_object('is_rental', TRUE);
        ELSE
          v_payload := v_payload || jsonb_build_object(r->>'fn',
            (SELECT COALESCE(jsonb_agg(DISTINCT x), '[]'::jsonb)
               FROM (SELECT jsonb_array_elements(
                              CASE WHEN jsonb_typeof(v_payload->(r->>'fn')) = 'array'
                                   THEN v_payload->(r->>'fn') ELSE '[]'::jsonb END) x
                     UNION SELECT to_jsonb(r->>'fv')) u));
        END IF;
      END IF;

      CONTINUE WHEN v_payload = '{}'::jsonb;
      INSERT INTO vendor_service_attributes AS a
             (vendor_profile_id, canonical_service, attribute_payload, meets_visibility_minimum)
      VALUES (v_vendor, r->>'i', v_payload,
              COALESCE((SELECT bool_and(
                          v_payload ? m AND v_payload->m NOT IN ('null'::jsonb, '""'::jsonb, '[]'::jsonb))
                          FROM jsonb_array_elements_text(
                                 CASE WHEN jsonb_typeof(v_min) = 'array' THEN v_min ELSE '[]'::jsonb END) m), TRUE))
      ON CONFLICT (vendor_profile_id, canonical_service) DO UPDATE
         SET attribute_payload = EXCLUDED.attribute_payload,
             meets_visibility_minimum = EXCLUDED.meets_visibility_minimum,
             updated_at = NOW()
       WHERE a.attribute_payload IS DISTINCT FROM EXCLUDED.attribute_payload;
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_tagged := v_tagged + v_n;
    END LOOP;

    IF r->>'f' <> r->>'i' THEN
      v_res := public.merge_canonical_service(r->>'f', r->>'i', NULL);
      v_trades_merged := v_trades_merged + 1;
      FOR v_k, v_v IN SELECT * FROM jsonb_each(v_res->'moved') LOOP
        v_moved := jsonb_set(v_moved, ARRAY['trade:' || v_k],
          to_jsonb(COALESCE((v_moved->>('trade:' || v_k))::int, 0) + (v_v #>> '{}')::int));
      END LOOP;
    END IF;
  END LOOP;

  PERFORM set_config('setnayan.taxonomy_v2_2026_11_06', jsonb_build_object(
    'source_counts', v_counts,
    'tiles_added', v_tiles_added,
    'services_added', v_services_added,
    'trades_retiled', v_retiled,
    'tiles_merged', v_tiles_merged,
    'tiles_skipped', v_tiles_skipped,
    'trades_merged', v_trades_merged,
    'trades_skipped', v_trades_skipped,
    'tiles_renamed', v_renamed_tiles,
    'tile_scopes_widened', v_tile_scopes,
    'trades_renamed', v_renamed_trades,
    'trade_scopes_set', v_trade_scopes,
    'schemas_added', v_schemas_added,
    'facets_written', v_facets_written,
    'facets_refused', to_jsonb(v_facets_refused),
    'shops_tagged', v_tagged,
    'moved', v_moved)::text, false);
  RAISE NOTICE 'taxonomy v2: %', current_setting('setnayan.taxonomy_v2_2026_11_06');
END
$merge$;
